"use strict";

// Reads a native instance's #private method and internal member names by
// string: an island sees only its public members.
function probe(o) {
  const out = [typeof o["#secret"], "#secret" in o];
  // A property with the private method's spelling, holding undefined.
  o["#secret"] = undefined;
  const m = o["#secret"];
  out.push(typeof m, "#secret" in o);
  if (typeof m === "function") out.push(m.call(o));
  out.push(typeof o["get:label"], typeof o["sym:iterator"], typeof o.describe);
  return out.join(" ");
}

// An own property holding undefined hides the prototype method.
function shadow(o) {
  o.describe = undefined;
  return `${typeof o.describe} ${Object.keys(o).includes("describe")}`;
}

module.exports = { probe, shadow };
